mapper.sql:
EXISTS (
    SELECT 1
      FROM CONTENT_SHARES s
     WHERE s.CONTENT_TYPE = #{contentType}
       AND s.CONTENT_ID = #{contentId}
       AND s.ACTIVE_YN = 'Y'
       AND NVL(s.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED'
       AND (s.EXPIRES_AT IS NULL OR s.EXPIRES_AT >= SYSDATE)
       AND (
            (s.TARGET_TYPE = 'USER' AND s.TARGET_ID = #{userId})
            OR (s.TARGET_TYPE = 'WS' AND EXISTS (
                SELECT 1 FROM WS_MEMBERS wm
                 WHERE wm.WS_ID = s.TARGET_ID
                   AND wm.USER_ID = #{userId}
            ))
            OR (s.TARGET_TYPE = 'PROJ' AND EXISTS (
                SELECT 1 FROM PROJ_MEMBERS pm
                 WHERE pm.PROJ_ID = s.TARGET_ID
                   AND pm.USER_ID = #{userId}
            ))
       )
)

EXISTS (
    SELECT 1
      FROM CONTENT_SHARES s
     WHERE s.CONTENT_TYPE = #{contentType}
       AND s.CONTENT_ID = #{contentId}
       AND s.ACTIVE_YN = 'Y'
       AND NVL(s.SHARE_STATUS, 'ACCEPTED') = 'ACCEPTED'
       AND UPPER(NVL(s.PERMISSION_TYPE, 'VIEW')) = 'EDIT'
       AND (s.EXPIRES_AT IS NULL OR s.EXPIRES_AT >= SYSDATE)
       AND (
            (s.TARGET_TYPE = 'USER' AND s.TARGET_ID = #{userId})
            OR (s.TARGET_TYPE = 'WS' AND EXISTS (
                SELECT 1 FROM WS_MEMBERS wm
                 WHERE wm.WS_ID = s.TARGET_ID
                   AND wm.USER_ID = #{userId}
            ))
            OR (s.TARGET_TYPE = 'PROJ' AND EXISTS (
                SELECT 1 FROM PROJ_MEMBERS pm
                 WHERE pm.PROJ_ID = s.TARGET_ID
                   AND pm.USER_ID = #{userId}
            ))
       )
)

mapper.delete:
DELETE FROM CONTENT_SHARES
 WHERE CONTENT_TYPE = #{contentType}
   AND CONTENT_ID = #{contentId}
   AND TARGET_TYPE = 'USER'
   AND TARGET_ID = #{ownerId}
   AND OWNER_ID = #{ownerId}
   AND SHARED_BY = #{ownerId}
   AND UPPER(NVL(PERMISSION_TYPE, 'VIEW')) = 'VIEW'

mapper.update:
DECLARE
    v_table_count NUMBER := 0;
    v_constraint_count NUMBER := 0;
BEGIN
    SELECT COUNT(*)
      INTO v_table_count
      FROM USER_TABLES
     WHERE TABLE_NAME = 'CONTENT_SHARES';

    IF v_table_count > 0 THEN
        SELECT COUNT(*)
          INTO v_constraint_count
          FROM USER_CONSTRAINTS
         WHERE TABLE_NAME = 'CONTENT_SHARES'
           AND CONSTRAINT_NAME = 'CK_CONTENT_SHARE_CONTENT';

        IF v_constraint_count > 0 THEN
            EXECUTE IMMEDIATE 'ALTER TABLE CONTENT_SHARES DROP CONSTRAINT CK_CONTENT_SHARE_CONTENT';
        END IF;

        EXECUTE IMMEDIATE 'ALTER TABLE CONTENT_SHARES ADD CONSTRAINT CK_CONTENT_SHARE_CONTENT CHECK (CONTENT_TYPE IN (''NOTE'',''PHOTO'',''ALBUM'',''BOARD'',''EVENT'',''CALENDAR'',''POLL'',''FILE'',''PERIOD_PLAN'',''WEEKLY_PLAN'',''TIME_PLAN''))';
    END IF;
END;

UPDATE CONTENT_SHARES s
   SET s.ACTIVE_YN = 'N',
       s.UPDATED_AT = SYSDATE
 WHERE s.SHARE_ID = #{shareId}
   AND s.OWNER_ID = #{userId}
   AND s.ACTIVE_YN = 'Y'

